update versions set definition = jsonb_set(jsonb_set(definition, '{language}', '"en"'), '{alt}', '{"language": "fr", "texts": {"title": "Notre nouvel atelier — votre avis", "intro": "Trois questions, une minute. Cela nous aide à prévoir les prochains changements.", "q30xxxxx": "Comment trouvez-vous le nouvel atelier ?", "q30xxxxx.c35xxxxx": "Mauvais", "q30xxxxx.c36xxxxx": "Moyen", "q30xxxxx.c37xxxxx": "Bien", "q30xxxxx.c38xxxxx": "Excellent", "q30xxxxx.r31xxxxx": "La lumière", "q30xxxxx.r32xxxxx": "Le bruit", "q30xxxxx.r33xxxxx": "La place à l’établi", "q30xxxxx.r34xxxxx": "Les outils à portée de main", "q40xxxxx": "Que devrions-nous améliorer en premier ?", "q40xxxxx.i41xxxxx": "Des établis plus grands", "q40xxxxx.i42xxxxx": "Une salle de finition plus calme", "q40xxxxx.i43xxxxx": "Une meilleure lumière", "q40xxxxx.i44xxxxx": "Un coin café", "q45xxxxx": "Autre chose ?"}}'::jsonb) where form_id = 7;

-- The contact form also makes a contact in Clients and opens a ticket in
-- Support (lib/routes.ts): which question gives what.
update forms set routes = '{"contact": {"name": "q1bxxxxx", "email": "q1cxxxxx", "phone": "q1dxxxxx", "company": null, "message": "q1ixxxxx"}, "request": {"subject": "q1hxxxxx", "details": "q1ixxxxx", "email": "q1cxxxxx", "name": "q1bxxxxx"}}'::jsonb where id = 5;

select setval(pg_get_serial_sequence('forms', 'id'), 100);

-- Round 3: where answers went (answers.sent) and a web address of the
-- feedback form (form_hooks; the harness's fake Chest does not know this
-- target, so Settings shows it as the tool recorded it).
update answers set sent = '{webhooks,copy}' where id = 'seed00000000000s';
