insert into versions (form_id, version, definition, published_at) values (1, 1, '{"title":"How did we do?","intro":"Two minutes of your time help our workshop a lot. Thank you!","pages":[{"id":"p7xxxxxx","title":"","questions":[{"id":"q1xxxxxx","kind":"rating","title":"How would you rate our service?","help":"","required":true,"steps":5},{"id":"q2xxxxxx","kind":"scale","title":"How likely are you to recommend Atelier Martin to a friend or colleague?","help":"","required":true,"from":0,"to":10,"left":"Not likely","right":"Very likely"}],"jumps":[{"when":{"question":"q2xxxxxx","op":"lt","value":7},"to":"p9xxxxxx"}]},{"id":"p8xxxxxx","title":"","questions":[{"id":"q3xxxxxx","kind":"long","title":"What did you like most?","help":"","required":false}],"jumps":[{"when":{"question":"q2xxxxxx","op":"answered"},"to":"paxxxxxx"}]},{"id":"p9xxxxxx","title":"","questions":[{"id":"q4xxxxxx","kind":"long","title":"What should we do better?","help":"","required":false}],"jumps":[]},{"id":"paxxxxxx","title":"","questions":[{"id":"q5xxxxxx","kind":"yesno","title":"May we contact you about your answers?","help":"","required":false},{"id":"q6xxxxxx","kind":"email","title":"Your email address","help":"","required":true,"showIf":{"question":"q5xxxxxx","op":"is","value":true}}],"jumps":[]}],"language":"en","alt":{"language":"fr","texts":{"title":"Comment nous sommes-nous débrouillés ?","intro":"Deux minutes de votre temps aident beaucoup notre atelier. Merci !","q1xxxxxx":"Comment notez-vous notre service ?","q2xxxxxx":"Recommanderiez-vous Atelier Martin à un ami ou un collègue ?","q2xxxxxx.left":"Peu probable","q2xxxxxx.right":"Très probable","q3xxxxxx":"Qu’avez-vous le plus apprécié ?","q4xxxxxx":"Que devrions-nous mieux faire ?","q5xxxxxx":"Pouvons-nous vous recontacter au sujet de vos réponses ?","q6xxxxxx":"Votre adresse e-mail"}}}'::jsonb, now() - interval '39 days');
