insert into versions (form_id, version, definition, published_at) values (2, 1, '{"title":"Open day — Saturday 14 November","intro":"Come and see the workshop at work. Tell us you are coming and we will save you a seat.","pages":[{"id":"plxxxxxx","title":"","questions":[{"id":"qbxxxxxx","kind":"short","title":"Your full name","help":"","required":true},{"id":"qcxxxxxx","kind":"email","title":"Your email address","help":"","required":true},{"id":"qdxxxxxx","kind":"short","title":"Your company","help":"","required":false},{"id":"qexxxxxx","kind":"number","title":"How many people are you?","help":"","required":true,"min":1,"max":10},{"id":"qkxxxxxx","kind":"choice","title":"Which workshop tour?","help":"","required":true,"options":[{"id":"ohxxxxxx","label":"10:00 — Wood and finishes"},{"id":"oixxxxxx","label":"14:00 — Upholstery"},{"id":"ojxxxxxx","label":"16:00 — Restoration"}]},{"id":"qfxxxxxx","kind":"yesno","title":"Will you stay for lunch?","help":"","required":true},{"id":"qgxxxxxx","kind":"short","title":"Any food we should know about?","help":"","required":false,"showIf":{"question":"qfxxxxxx","op":"is","value":true}}],"jumps":[]}],"language":"en","alt":{"language":"fr","texts":{"title":"Portes ouvertes — samedi 14 novembre","intro":"Venez voir l’atelier au travail. Dites-nous que vous venez, nous vous garderons une place.","qbxxxxxx":"Vos nom et prénom","qcxxxxxx":"Votre adresse e-mail","qdxxxxxx":"Votre entreprise","qexxxxxx":"Combien serez-vous ?","qkxxxxxx":"Quelle visite d’atelier ?","qkxxxxxx.ohxxxxxx":"10 h — Bois et finitions","qkxxxxxx.oixxxxxx":"14 h — Tapisserie","qkxxxxxx.ojxxxxxx":"16 h — Restauration","qfxxxxxx":"Resterez-vous déjeuner ?","qgxxxxxx":"Un régime alimentaire à connaître ?"}}}'::jsonb, now() - interval '11 days');
