insert into versions (form_id, version, definition, published_at) values (3, 1, '{"title":"IT request","intro":"Tell us what is wrong. We come back to you quickly.","pages":[{"id":"p11xxxxx","title":"","questions":[{"id":"qpxxxxxx","kind":"choice","title":"What do you need?","help":"","required":true,"options":[{"id":"omxxxxxx","label":"Something is broken"},{"id":"onxxxxxx","label":"New equipment"},{"id":"ooxxxxxx","label":"Access to a tool"}],"other":true},{"id":"quxxxxxx","kind":"dropdown","title":"Which device?","help":"","required":false,"options":[{"id":"oqxxxxxx","label":"Laptop"},{"id":"orxxxxxx","label":"Phone"},{"id":"osxxxxxx","label":"Printer"},{"id":"otxxxxxx","label":"Screen"}],"showIf":{"question":"qpxxxxxx","op":"is_not","value":"ooxxxxxx"}},{"id":"qyxxxxxx","kind":"choice","title":"How urgent is it?","help":"","required":true,"options":[{"id":"ovxxxxxx","label":"I cannot work"},{"id":"owxxxxxx","label":"It slows me down"},{"id":"oxxxxxxx","label":"It can wait"}]},{"id":"qzxxxxxx","kind":"long","title":"Describe it in a few words","help":"","required":true},{"id":"q10xxxxx","kind":"file","title":"A photo or a screenshot","help":"","required":false,"accept":"images"}],"jumps":[]}],"language":"en","alt":{"language":"fr","texts":{"title":"Demande informatique","intro":"Dites-nous ce qui ne va pas. Nous revenons vers vous vite.","qpxxxxxx":"De quoi avez-vous besoin ?","qpxxxxxx.omxxxxxx":"Quelque chose est en panne","qpxxxxxx.onxxxxxx":"Un nouvel équipement","qpxxxxxx.ooxxxxxx":"Un accès à un outil","quxxxxxx":"Quel appareil ?","quxxxxxx.oqxxxxxx":"Ordinateur portable","quxxxxxx.orxxxxxx":"Téléphone","quxxxxxx.osxxxxxx":"Imprimante","quxxxxxx.otxxxxxx":"Écran","qyxxxxxx":"C’est urgent ?","qyxxxxxx.ovxxxxxx":"Je ne peux pas travailler","qyxxxxxx.owxxxxxx":"Ça me ralentit","qyxxxxxx.oxxxxxxx":"Ça peut attendre","qzxxxxxx":"Décrivez-le en quelques mots","q10xxxxx":"Une photo ou une capture d’écran"}}}'::jsonb, now() - interval '59 days');
